<script setup>
import {computed} from 'vue'
import SvgIcon from '../ui/SvgIcon.vue'
const props=defineProps({total:Number,onsite:Number})
const channels=computed(()=>[{name:'Выезд к клиенту',icon:'home',value:props.onsite,color:'var(--blue)'},{name:'Ремонт в сервисе',icon:'store',value:props.total-props.onsite,color:'var(--purple)'}].map((c,i)=>({...c,percent:props.total?(i?100-Math.round(props.onsite/props.total*100):Math.round(props.onsite/props.total*100)):0})))
</script>
<template><div class="channel-chart"><svg viewBox="0 0 220 220" role="img" :aria-label="channels.map(c=>c.name+': '+c.value).join(', ')"><circle cx="110" cy="110" r="84" fill="none" stroke="var(--border)" stroke-width="1"/><circle cx="110" cy="110" r="62" fill="none" stroke="var(--border)" stroke-width="1"/><g transform="rotate(-90 110 110)"><circle cx="110" cy="110" r="73" fill="none" stroke="var(--surface2)" stroke-width="19"/><circle v-for="(c,i) in channels" :key="i" cx="110" cy="110" r="73" fill="none" :stroke="c.color" stroke-width="19" stroke-linecap="round" pathLength="100" :stroke-dasharray="`${Math.max(0,c.percent-2)} ${102-c.percent}`" :stroke-dashoffset="i?-channels[0].percent:0" class="channel-ring" v-show="c.value"/></g><text x="110" y="108" text-anchor="middle" fill="var(--text)" font-size="36" font-weight="750">{{total}}</text><text x="110" y="129" text-anchor="middle" fill="var(--muted)" font-size="12">обращений</text></svg><div class="channel-details"><div v-for="c in channels" :key="c.name" class="channel-row"><span class="channel-icon" :style="{color:c.color,background:`color-mix(in srgb,${c.color} 12%,transparent)`}"><SvgIcon :name="c.icon" :size="19"/></span><div><span>{{c.name}}</span><div class="channel-meter"><i :style="{width:c.percent+'%',background:c.color}"/></div></div><strong>{{c.value}}<small>{{c.percent}}%</small></strong></div></div></div></template>
<style scoped>.channel-chart{display:grid;justify-items:center;gap:12px;padding-top:12px}.channel-chart>svg{width:min(100%,220px);height:220px}.channel-details{width:100%;display:grid;gap:14px}.channel-row{display:flex;align-items:center;gap:11px;padding:12px;background:color-mix(in srgb,var(--surface2) 50%,transparent);border:1px solid var(--border);border-radius:13px}.channel-icon{width:37px;height:37px;border-radius:11px;display:grid;place-items:center;flex-shrink:0}.channel-row>div{flex:1;min-width:0;font-size:13px}.channel-meter{height:4px;background:var(--border);border-radius:5px;margin-top:10px;overflow:hidden}.channel-meter i{display:block;height:100%;border-radius:5px;transition:width .6s}.channel-row strong{text-align:right;font-size:18px}.channel-row small{display:block;font-size:12px;color:var(--muted);font-weight:400}.channel-ring{transition:stroke-dasharray .6s,stroke-dashoffset .6s}@media(prefers-reduced-motion:reduce){.channel-ring,.channel-meter i{transition:none}}</style>
